  package    jenkins . plugins . coverity . Utils ;   import    jenkins . plugins . coverity . CIMInstance ;   public class CIMInstanceBuilder  {   private String  name ;   private String  host ;   private  int  port ;   private String  credentialId ;   private boolean  useSSL ;   public CIMInstanceBuilder withName  (  String name )  {    this . name = name ;  return this ; }   public CIMInstanceBuilder withHost  (  String host )  {    this . host = host ;  return this ; }   public CIMInstanceBuilder withPort  (   int port )  {    this . port = port ;  return this ; }   public CIMInstanceBuilder withCredentialId  (  String credentialId )  {    this . credentialId = credentialId ;  return this ; }   public CIMInstanceBuilder withDefaultCredentialId  ( )  {    this . credentialId = "DefaultCredentialId" ;  return this ; }   public CIMInstanceBuilder withUseSSL  (  boolean useSSL )  {    this . useSSL = useSSL ;  return this ; }   public CIMInstance build  ( )  {  CIMInstance  instance =  new CIMInstance  ( name , host , port , credentialId ) ;   instance . setUseSSL  ( useSSL ) ;  return instance ; } }